import React, { useState } from 'react';

type Car = {
  id: number;
  brand: string;
  model: string;
  year: string;
  price: string;
  mileage: string;
  vin: string;
  features: string[];
};

const mockCars: Car[] = [
  {
    id: 1,
    brand: 'Toyota',
    model: 'Corolla',
    year: '2020',
    price: '15000',
    mileage: '50000',
    vin: '1234567890ABCDEF1',
    features: ['Навигация', 'Кожен салон'],
  },
  {
    id: 2,
    brand: 'BMW',
    model: 'X5',
    year: '2019',
    price: '32000',
    mileage: '70000',
    vin: '9876543210ZYXWVU2',
    features: ['Климатик', 'Парктроник'],
  },
  {
    id: 3,
    brand: 'Audi',
    model: 'A4',
    year: '2022',
    price: '28000',
    mileage: '30000',
    vin: 'A1B2C3D4E5F6G7H8',
    features: ['Навигация', 'Парктроник'],
  },
];

type Filters = {
  brand: string;
  model: string;
  year: string;
  price: string;
  mileage: string;
  vin: string;
  features: string[];
};

const featuresList = ['Навигация', 'Климатик', 'Кожен салон', 'Парктроник'];

const SearchCar: React.FC = () => {
  const [filters, setFilters] = useState<Filters>({
    brand: '',
    model: '',
    year: '',
    price: '',
    mileage: '',
    vin: '',
    features: [],
  });

  const [results, setResults] = useState<Car[]>([]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const handleFeaturesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { value, checked } = e.target;
    setFilters(prev => ({
      ...prev,
      features: checked
        ? [...prev.features, value]
        : prev.features.filter(f => f !== value),
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const filtered = mockCars.filter(car =>
      (!filters.brand || car.brand.toLowerCase().includes(filters.brand.toLowerCase())) &&
      (!filters.model || car.model.toLowerCase().includes(filters.model.toLowerCase())) &&
      (!filters.year || car.year === filters.year) &&
      (!filters.price || car.price === filters.price) &&
      (!filters.mileage || car.mileage === filters.mileage) &&
      (!filters.vin || car.vin.includes(filters.vin)) &&
      filters.features.every(f => car.features.includes(f))
    );
    setResults(filtered);
  };

  return (
    <div className="max-w-5xl mx-auto p-10 bg-white rounded-2xl shadow mt-10">
      <h1 className="text-3xl font-bold text-center mb-6">Търсене на автомобили</h1>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
        <div>
          <label className="block text-sm mb-1">Марка</label>
          <input
            name="brand"
            value={filters.brand}
            onChange={handleChange}
            placeholder="напр. Toyota"
            className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm mb-1">Модел</label>
          <input
            name="model"
            value={filters.model}
            onChange={handleChange}
            placeholder="напр. Corolla"
            className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm mb-1">Година на производство</label>
          <input
            name="year"
            value={filters.year}
            onChange={handleChange}
            placeholder="2020"
            className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm mb-1">Цена</label>
          <input
            name="price"
            value={filters.price}
            onChange={handleChange}
            placeholder="15000"
            className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm mb-1">Пробег (км)</label>
          <input
            name="mileage"
            value={filters.mileage}
            onChange={handleChange}
            placeholder="50000"
            className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm mb-1">VIN номер</label>
          <input
            name="vin"
            value={filters.vin}
            onChange={handleChange}
            placeholder="ABC123..."
            className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2"
          />
        </div>

        <div className="md:col-span-3">
          <label className="block text-sm mb-1">Екстри</label>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
            {featuresList.map(feature => (
              <label key={feature} className="flex items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  value={feature}
                  checked={filters.features.includes(feature)}
                  onChange={handleFeaturesChange}
                  className="accent-purple-600"
                />
                {feature}
              </label>
            ))}
          </div>
        </div>

        <div className="md:col-span-3 text-center">
          <button
            type="submit"
            className="bg-purple-600 text-white px-6 py-2 rounded-full hover:bg-purple-700"
          >
            Търси
          </button>
        </div>
      </form>

      <div>
        <h2 className="text-xl font-semibold mb-4">Резултати:</h2>
        {results.length === 0 ? (
          <p className="text-gray-500">Няма намерени коли по зададените критерии.</p>
        ) : (
          <ul className="space-y-4">
            {results.map(car => (
              <li key={car.id} className="p-4 bg-gray-100 rounded-lg shadow">
                <p><strong>{car.brand} {car.model}</strong> — {car.year} г.</p>
                <p>Цена: {car.price} € | Пробег: {car.mileage} км</p>
                <p>VIN: {car.vin}</p>
                <p>Екстри: {car.features.join(', ')}</p>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default SearchCar;
